  coffee: () => `<path d="M-130 20 Q-150 -40 -80 -50 Q-60 -100 0 -80 Q60 -110 90 -50 Q160 -40 130 20 Q140 70 70 60 Q20 100 -40 70 Q-130 90 -130 20 Z" fill="#7a4a2a" ${S(6)}/>`,
